<?php
require_once __DIR__.'/../modelos/Campania.php';require_once __DIR__.'/../modelos/Vendedor.php';
class HomeController {
 private $db;
 function __construct($db){$this->db=$db;}
 function inicio(){if(usuarioActual()){header('Location: index.php?c=home&a=panel');exit;}require __DIR__.'/../vistas/home/inicio.php';}
 private function scalar($sql,$id){$s=$this->db->prepare($sql);$s->bind_param('i',$id);$s->execute();return (float)$s->get_result()->fetch_assoc()['valor'];}
 function panel(){requiereSesion();$id=(int)usuarioActual()['id'];$stats=['vendido'=>0,'stock'=>0,'vendedores'=>0,'recaudado'=>0,'pendiente'=>0];$campania=null;$movimientos=[];$stockBajo=[];$masVendidos=[];$campanias=[];$asignacionesVendedor=[];
 if(esAdministrador()){$campanias=(new Campania($this->db))->listarActivas($id);$seleccion=(int)($_GET['campania_id']??($campanias[0]['id']??0));foreach($campanias as $c){if((int)$c['id']===$seleccion)$campania=$c;}if(!$campania&&$campanias)$campania=$campanias[0];if($campania){$cid=(int)$campania['id'];$stats['vendido']=$this->scalar('SELECT COALESCE(SUM(v.total),0) valor FROM ventas v JOIN vendedores_campanias vc ON vc.id=v.vendedor_campania_id WHERE vc.campania_id=?',$cid);$stats['recaudado']=$this->scalar('SELECT COALESCE(SUM(p.monto),0) valor FROM pagos p JOIN vendedores_campanias vc ON vc.id=p.vendedor_campania_id WHERE vc.campania_id=?',$cid);$stats['stock']=$this->scalar('SELECT COALESCE(SUM(stock_actual),0) valor FROM productos WHERE activo=1 AND campania_id=?',$cid);$stats['vendedores']=$this->scalar("SELECT COUNT(*) valor FROM vendedores_campanias WHERE estado='ACTIVO' AND campania_id=?",$cid);$stats['pendiente']=max(0,$stats['vendido']-$stats['recaudado']);$s=$this->db->prepare('SELECT v.fecha_venta fecha,CONCAT(\'Venta a \',v.cliente) detalle,v.total monto FROM ventas v JOIN vendedores_campanias vc ON vc.id=v.vendedor_campania_id WHERE vc.campania_id=? ORDER BY v.id DESC LIMIT 5');$s->bind_param('i',$cid);$s->execute();$movimientos=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s=$this->db->prepare('SELECT nombre,stock_actual FROM productos WHERE activo=1 AND campania_id=? AND stock_actual<=stock_minimo ORDER BY stock_actual LIMIT 5');$s->bind_param('i',$cid);$s->execute();$stockBajo=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s=$this->db->prepare('SELECT p.nombre,SUM(d.cantidad) cantidad FROM detalle_ventas d JOIN productos p ON p.id=d.producto_id WHERE p.campania_id=? GROUP BY p.id ORDER BY cantidad DESC LIMIT 5');$s->bind_param('i',$cid);$s->execute();$masVendidos=$s->get_result()->fetch_all(MYSQLI_ASSOC);}}
 else {$stats['vendido']=$this->scalar('SELECT COALESCE(SUM(v.total),0) valor FROM ventas v JOIN vendedores_campanias vc ON vc.id=v.vendedor_campania_id WHERE vc.vendedor_id=?',$id);$stats['recaudado']=$this->scalar('SELECT COALESCE(SUM(p.monto),0) valor FROM pagos p JOIN vendedores_campanias vc ON vc.id=p.vendedor_campania_id WHERE vc.vendedor_id=?',$id);$rendido=$this->scalar("SELECT COALESCE(SUM(r.monto_declarado),0) valor FROM rendiciones r JOIN vendedores_campanias vc ON vc.id=r.vendedor_campania_id WHERE vc.vendedor_id=? AND r.estado='APROBADA'",$id);$stats['pendiente']=max(0,$stats['recaudado']-$rendido);$asignacionesVendedor=(new Vendedor($this->db))->asignacionesVendedor($id);}
 require __DIR__.'/../vistas/home/panel.php';}
 function buscar(){requiereSesion();$texto=trim((string)($_GET['q']??''));$resultados=[];if($texto!==''){$buscar='%'.$texto.'%';$id=(int)usuarioActual()['id'];if(esAdministrador()){$consultas=[['Campaña','SELECT id,nombre titulo,descripcion detalle FROM campanias WHERE creado_por=? AND (nombre LIKE ? OR descripcion LIKE ?)','index.php?c=campania&a=inicio'],['Producto','SELECT p.id,p.nombre titulo,p.descripcion detalle FROM productos p JOIN campanias c ON c.id=p.campania_id WHERE c.creado_por=? AND (p.nombre LIKE ? OR p.descripcion LIKE ?)','index.php?c=producto&a=inicio']];foreach($consultas as [$tipo,$sql,$url]){$s=$this->db->prepare($sql);$s->bind_param('iss',$id,$buscar,$buscar);$s->execute();foreach($s->get_result()->fetch_all(MYSQLI_ASSOC) as $r){$r['tipo']=$tipo;$r['url']=$url;$resultados[]=$r;}}}}require __DIR__.'/../vistas/home/buscar.php';}
}
